    const step=one(steps,item=>item.id==='M4.2.refresh'&&item.logicalCase==='M4.2'&&same(item.response.window,request.response.window),'The actual selected refresh step/window must be exact');assert(step.response.status===200);assert.equal(request.path,'/api/project-handovers/'+row.target_id+'/attachment-checklist:refresh');assert(row.target_type===source.targetType&&row.relation_type===source.relationType&&row.status===source.active&&row.unlinked_at===null&&row.unlinked_by===null);
