    const registerSourceText=(value,slot)=>{assert(typeof value==='string'&&typeof slot==='string');const mapped='$source-input:'+slot;if(texts.has(value))assert.equal(texts.get(value),mapped,'One exact prepared source literal cannot name different input slots');else texts.set(value,mapped)};
    const termDefault=termDefaultMetadata?verifyAttachmentKTermDefault({journal,types,k,metadata:termDefaultMetadata,originalLedgerRef,sourceEngine}):null;
